@app.post("/api/voice")
async def voice(
    audio: UploadFile = File(...),
    sector: str = Form("Other"),
):
    """Audio of a voice note -> transcript + listing fields.

    Without a configured speech model, the sector sample transcript
    is returned and `demo` will be true.
    """

    data = await audio.read()

    if len(data) > 8_000_000:
        raise HTTPException(
            status_code=413,
            detail="Voice note is too long. Keep it under a minute.",
        )

    c = content()

    sec = c["sectors"].get(
        sector,
        c["sectors"]["Other"],
    )

    suffix = (
        Path(
            audio.filename
            or "note.webm"
        ).suffix
        or ".webm"
    )

    text = ai.transcribe(
        data,
        suffix,
    )

    demo = text is None

    if demo:
        text = sec["sample"]

    listing = ai.extract_listing(
        text,
        sec["suffix"],
    )

    return {
        "transcript": text,
        "demo": demo,
        "listing": listing,
    }


