// Address of the backend. Leave "" to run with no backend: everything then stays on one device.
// Example: window.YOLO_CONFIG = { api: "https://yolowisata-api.example.com" };
// When the backend itself serves this website (run.sh), use the same address the site is opened on, or "" plus a reverse proxy.
window.YOLO_CONFIG = { api: "" };
"""The small AI used by the backend.

Everything here has a rule-based version that needs no model, so the demo never breaks.
Real models are optional and switched on with settings in .env:
  - speech-to-text: YOLO_WHISPER_MODEL (needs `pip install faster-whisper`)
Translation and theme analysis with a language model are not wired in yet; see docs/DATA.md.
"""
import os, re, tempfile

NUM = {"satu": 1, "dua": 2, "tiga": 3, "empat": 4, "lima": 5, "enam": 6}
ACTS = [("keliling", "A guided walk"), ("petik", "Picking coffee cherries"), ("sangrai", "Roasting your own coffee"),
        ("minum", "Drinking the coffee"), ("cicip", "Tasting"), ("ukir", "Wood carving"), ("membuat", "Making your own piece"),
        ("pasar", "Market shopping"), ("masak", "Cooking together"), ("tenun", "Weaving")]
DAYS = [("senin", "Monday"), ("selasa", "Tuesday"), ("rabu", "Wednesday"), ("kamis", "Thursday"),
        ("jumat", "Friday"), ("sabtu", "Saturday"), ("minggu", "Sunday")]


def extract_listing(text: str, suffix: str = "Experience", place: str = "the village") -> dict:
    """Voice transcript (Bahasa Indonesia) -> listing fields. Same rules as extract() in frontend/app.js.
    A field that was not heard is simply left out. Nothing is guessed."""
    s, o = text.lower(), {}
    m = re.search(r"nama saya ([a-z]+)", s)
    if m:
        o["name"] = m.group(1).capitalize() + "â€™s " + ("Coffee Farm Experience" if "kopi" in s else suffix)
    m = re.search(r"(\d{2,4})\s*(?:[.,]000|ribu|rb)", s)
    if m:
        o["price"] = "Rp" + m.group(1) + ".000 per person"
    m = re.search(r"(\d+|satu|dua|tiga|empat|lima|enam)\s*jam", s)
    if m:
        o["duration"] = "About %s hours" % NUM.get(m.group(1), m.group(1))
    acts = [en for key, en in ACTS if key in s]
    if acts:
        o["activities"] = ", ".join(acts)
    days = [en for key, en in DAYS if key in s]
    if "setiap hari" in s:
        o["availability"] = "Every day"
    elif days:
        o["availability"] = " and ".join(days) + (" mornings" if "pagi" in s else "")
    if acts:
        lead = o["duration"].replace("About ", "A ").replace(" hours", "-hour") + " visit" if "duration" in o else "A visit"
        o["description"] = "%s in %s: %s." % (lead, place, o["activities"].lower())
    o["missing"] = [k for k in ("name", "description", "price", "duration", "activities", "availability") if k not in o]
    return o


def _tags(text: str, lex: dict) -> list:
    s = text.lower()
    return [k for k, v in lex.items() if any(w in s for w in v["words"])]


def evidence_label(n: int) -> str:
    return "Strong pattern" if n >= 6 else "Early signal" if n >= 3 else "Not enough evidence yet"


def analyse(business: dict, themes: dict, postcards: list, messages: list) -> dict:
    """Experience DNA: count themes in postcards, questions and guest messages. Same logic as analyse() in app.js.
    Every count comes with the quotes behind it and a label, so the owner can check it."""
    loved_lex = {k: dict(v) for k, v in themes["loved"].items()}
    if "host" in loved_lex:
        loved_lex["host"]["words"] = loved_lex["host"]["words"] + [business["host"].lower().split(" ")[-1]]
    cards = list(business.get("cards", [])) + [p for p in postcards if p.get("biz") == business["id"]]
    qs = list(business.get("qs", [])) + [
        {"f": m.get("f", ""), "t": m["t"], "loc": 1 if m.get("f") == "ðŸ‡®ðŸ‡©" else 0}
        for m in messages if m.get("from") == "g" and str(m.get("thread", "")).startswith(business["id"] + ":")]
    out = {"loved": {}, "asks": {}, "segments": {"international": {}, "local": {}}}

    def add(group, key, quote):
        e = out[group].setdefault(key, {"count": 0, "quotes": []})
        e["count"] += 1
        e["quotes"].append(quote)

    for c in cards:
        for k in _tags(c["t"], loved_lex):
            add("loved", k, c["t"])
        for k in _tags(c["t"], themes["asks"]):
            add("asks", k, c["t"])
    for q in qs:
        for k in _tags(q["t"], themes["asks"]):
            add("asks", k, q["t"])
            seg = out["segments"]["local" if q.get("loc") else "international"]
            seg[k] = seg.get(k, 0) + 1
    for group in ("loved", "asks"):
        for e in out[group].values():
            e["label"] = evidence_label(e["count"])
    out["postcards"], out["questions"] = len(cards), len(qs)
    return out


_model = None


def transcribe(audio: bytes, suffix: str = ".webm"):
    """Speech-to-text. Returns the transcript, or None when no speech model is set up
    (the caller then falls back to a sample transcript and says so)."""
    global _model
    name = os.environ.get("YOLO_WHISPER_MODEL", "").strip()
    if not name:
        return None
    try:
        from faster_whisper import WhisperModel
        if _model is None:
            _model = WhisperModel(name, device="cpu", compute_type="int8")
        with tempfile.NamedTemporaryFile(suffix=suffix) as f:
            f.write(audio)
            f.flush()
            segments, _ = _model.transcribe(f.name, language=os.environ.get("YOLO_LANG", "id"))
            return " ".join(seg.text.strip() for seg in segments).strip() or None
    except Exception as e:  # model missing, bad audio, etc: never break the demo
        print("transcribe failed:", e)
        return None
"""YoloWisata backend: a small FastAPI server.

It does three things:
  1. shares postcards, messages, bookings, listings and new businesses between phones,
  2. runs the small AI (voice note -> listing, visitor insights),
  3. serves the website itself so one command runs everything locally.

Current migration state:
  - Supabase backs read endpoints, visitor insights and postcard writes.
  - data/store.json is temporarily preserved for legacy frontend sync/write compatibility.

Run from the project root:

    uvicorn backend.main:app --reload --host 127.0.0.1 --port 8001
"""

import json
import os
import threading
from datetime import datetime, timezone
from pathlib import Path
from uuid import NAMESPACE_URL, UUID, uuid5

from pydantic import BaseModel, Field, StrictBool, ValidationError

from fastapi import (
    FastAPI,
    File,
    Form,
    HTTPException,
    Request,
    UploadFile,
)
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse
from fastapi.staticfiles import StaticFiles

from backend.database import supabase


try:
    from . import ai
except ImportError:
    # Allows running from inside backend/ if needed.
    import ai


# ============================================================
# PATHS / CONFIG
# ============================================================

ROOT = Path(__file__).resolve().parent.parent

CONTENT = ROOT / "data" / "content.json"

STORE = Path(
    os.environ.get(
        "YOLO_STORE",
        ROOT / "data" / "store.json",
    )
)

KINDS = {
    "postcards",
    "messages",
    "bookings",
    "bookingstatus",
    "listings",
    "businesses",
}

REQUIRED = {
    "postcards": ("biz", "t"),
    "messages": ("thread", "t", "from"),
    "bookings": ("biz", "date", "people"),
    "bookingstatus": ("status",),
    "listings": ("L",),
    "businesses": ("name", "host", "sector"),
}

# Per record.
# Postcard photos are shrunk by the website before sending.
MAX_BYTES = 200_000


# ============================================================
# FASTAPI APP
# ============================================================

app = FastAPI(
    title="YoloWisata API",
    version="0.2.0",
)

app.add_middleware(
    CORSMiddleware,
    allow_origins=os.environ.get(
        "YOLO_ORIGINS",
        "*",
    ).split(","),
    allow_methods=["*"],
    allow_headers=["*"],
)

_lock = threading.Lock()


# ============================================================
# LEGACY CONTENT / STORE HELPERS
# ============================================================

def content() -> dict:
    """Load the static destination/product content."""
    return json.loads(
        CONTENT.read_text(
            encoding="utf-8",
        )
    )


def load() -> dict:
    """Load the temporary JSON shared-data store."""

    if STORE.exists():
        try:
            return json.loads(
                STORE.read_text(
                    encoding="utf-8",
                )
            )

        except json.JSONDecodeError:
            pass

    return {
        kind: {}
        for kind in KINDS
    }


def save(store: dict) -> None:
    """Atomically save the temporary JSON shared-data store."""

    tmp = STORE.with_suffix(".tmp")

    tmp.write_text(
        json.dumps(
            store,
            ensure_ascii=False,
        ),
        encoding="utf-8",
    )

    tmp.replace(STORE)


# ============================================================
# HEALTH
# ============================================================

@app.get("/api/health")
def health():
    """Check backend, Supabase and optional speech-model status."""

    database_connected = False
    database_error = None

    try:
        (
            supabase
            .table("destinations")
            .select("id")
            .limit(1)
            .execute()
        )

        database_connected = True

    except Exception as exc:
        database_error = str(exc)

    return {
        "ok": True,
        "database": {
            "connected": database_connected,
            "provider": "supabase",
            "error": database_error,
        },
        "speech_model": bool(
            os.environ.get(
                "YOLO_WHISPER_MODEL",
                "",
            ).strip()
        ),
    }


# ============================================================
# STATIC PRODUCT CONTENT
# ============================================================

@app.get("/api/content")
def get_content():
    """Return static destination/product content."""

    return content()


# ============================================================
# LEGACY SYNC
#
# Temporary compatibility endpoint.
# The existing frontend still polls this endpoint.
# ============================================================

@app.get("/api/sync")
def sync():
    """Return everything currently stored in the legacy JSON store."""

    store = load()

    return {
        kind: store.get(
            kind,
            {},
        )
        for kind in KINDS
    }


# ============================================================
# SUPABASE READ ENDPOINTS
# ============================================================


# ------------------------------------------------------------
# BUSINESSES
# ------------------------------------------------------------

@app.get("/api/businesses")
def get_businesses():
    """Return active businesses from Supabase."""

    try:
        result = (
            supabase
            .table("businesses")
            .select("*")
            .eq(
                "is_active",
                True,
            )
            .execute()
        )

        return {
            "ok": True,
            "businesses": result.data,
        }

    except Exception as exc:
        raise HTTPException(
            status_code=500,
            detail=f"Failed to fetch businesses: {exc}",
        )


@app.get("/api/businesses/{biz_id}")
def get_business(biz_id: str):
    """Return one business from Supabase."""

    try:
        result = (
            supabase
            .table("businesses")
            .select("*")
            .eq(
                "id",
                biz_id,
            )
            .limit(1)
            .execute()
        )

        if not result.data:
            raise HTTPException(
                status_code=404,
                detail="Business not found.",
            )

